function dy = FoodChain(~,y,b1)
    % parameters
    r=1;  K=1;    c1=1; c2=1;
    a1=5; a2=0.1; b2=2; d1=0.4; d2=0.01;
    % default for b1
    if (nargin &lt; 3), b1 = 2.0; end
    % rhs
    X = y(1);
    Y = y(2);
    Z = y(3);
    dX = r*X.*(1-X/K)-a1*X./(1+b1*X).*Y;
    dY = c1*a1*X./(1+b1*X).*Y-d1*Y-a2*Y./(1+b2*Y).*Z;
    dZ = c2*a2*Y./(1+b2*Y).*Z-d2*Z;
    dy = [dX;dY;dZ];
end




