tdur = 10.0;
Vclamp = @(t) V0 + (V1-V0).*(t &gt;= t0).*(t &lt;= t0 + tdur);
I_clamp = @(t,V) -kappa*(V - Vclamp(t));
hhmodel_clamped = @(t,y) hhmodel(t,y,'Istim',I_clamp);

sol = ode15s(hhmodel_clamped, [0 20.0], y0);
[~,currents,params] = hhmodel_clamped(sol.x,sol.y);
